(6, 3, 1, 2, 'Sabores Zenú de Sampués', 'Cocina del pueblo Zenú en Sampués: preparaciones con maíz, yuca y ñame, contadas por una familia de artesanos.', 3.0, 60000.00, 15, 'Llegar 15 minutos antes.', 'ACTIVA', '2026-11-22 22:44:13'),
(7, 8, 1, 6, 'Asado sabanero en Corozal', 'Asado sabanero en una finca de Corozal con carne de res a la brasa, bollo y ensalada, acompañado de música de acordeón.', 3.5, 75000.00, 20, 'Menores de edad con acompañante.', 'ACTIVA', '2026-11-22 22:44:13'),
(8, 4, 2, 4, 'Pasadía en la Ciénaga de la Caimanera en Coveñas', 'Pasadía ecológico en la Ciénaga de la Caimanera: recorrido en canoa por el manglar, descanso en la playa y almuerzo de pescado fresco.', 6.0, 95000.00, 20, 'Llegar 15 minutos antes.', 'ACTIVA', '2026-11-22 22:44:13'),
(9, 9, 2, 5, 'Atardecer en Rincón del Mar', 'Tarde tranquila en Rincón del Mar, San Onofre: caminata por la playa, baño en el mar y atardecer con coctel de frutas.', 4.0, 80000.00, 20, 'Menores de edad con acompañante.', 'ACTIVA', '2026-11-22 22:44:13'),
(10, 5, 2, 8, 'Senderismo en los Montes de María - Colosó', 'Caminata guiada por el bosque seco tropical de los Montes de María en Colosó, con miradores, quebradas y avistamiento de monos aulladores.', 5.0, 90000.00, 15, 'Menores de edad con acompañante.', 'ACTIVA', '2026-11-22 22:44:13'),
(11, 7, 6, 13, 'Aves de La Mojana', 'Avistamiento de aves en los humedales de La Mojana al amanecer, en canoa y con guía local experto en especies acuáticas.', 6.0, 110000.00, 10, 'Llevar hidratación y gorra.', 'ACTIVA', '2026-11-22 22:44:13'),
(12, 7, 6, 13, 'Pesca artesanal en la ciénaga', 'Jornada con pescadores de la ciénaga en Majagual: técnicas de atarraya, recorrido en chalupa y fritura del pescado capturado.', 4.0, 70000.00, 8, 'Usar ropa cómoda y protector solar.', 'ACTIVA', '2026-11-22 22:44:13'),
(13, 9, 1, 5, 'Cata de mariscos y maridaje en San Onofre', 'Cata de mariscos en San Onofre con menú de tres tiempos y maridaje con bebidas tradicionales del Caribe.', 3.0, 130000.00, 12, 'Menores de edad con acompañante.', 'ACTIVA', '2026-11-22 22:44:13'),
(14, 9, 6, 5, 'Manglar y conservación', 'Experiencia de conservación en San Onofre: siembra de mangle, charla sobre el ecosistema y recorrido en kayak.', 3.0, 60000.00, 12, 'Llegar 15 minutos antes.', 'ACTIVA', '2026-11-22 22:44:13'),
(15, 8, 3, 6, 'Noche de fandango sabanero', 'Noche de fandango en Corozal: rueda de baile alrededor de la banda de viento, con velas encendidas como en las fiestas patronales.', 3.0, 45000.00, 30, 'Menores de edad con acompañante.', 'ACTIVA', '2026-11-22 22:44:13'),
(16, 6, 3, 1, 'Historia de Sincelejo a pie', 'Recorrido a pie por el centro histórico de Sincelejo: catedral, plaza Majagual y la historia de las corralejas.', 2.0, 35000.00, 25, 'Menores de edad con acompañante.', 'ACTIVA', '2026-11-22 22:44:13'),
(17, 3, 3, 2, 'El sombrero vueltiao por dentro', 'Visita al centro artesanal de Sampués para conocer cómo se fabrica el sombrero vueltiao, desde la caña flecha hasta el trenzado final.', 2.5, 50000.00, 15, 'Llevar hidratación y gorra.', 'ACTIVA', '2026-11-22 22:44:13'),
(18, 5, 3, 12, 'Música de gaitas y tambores', 'Encuentro con músicos de gaita y tambor en Ovejas, cuna del Festival Nacional de Gaitas, con taller corto de percusión.', 2.5, 40000.00, 30, 'Llevar hidratación y gorra.', 'ACTIVA', '2026-11-22 22:44:13'),
(19, 10, 3, 7, 'Ruta de la Gaita y la Hamaca en Morroa', 'Ruta por Morroa entre la música de gaita y los telares donde se tejen las hamacas que hicieron famoso al pueblo.', 4.0, 85000.00, 10, 'Llegar 15 minutos antes.', 'ACTIVA', '2026-11-22 22:44:13'),
(20, 3, 5, 2, 'Trenzado de caña flecha', 'Taller de trenzado de caña flecha con artesanos zenúes: cada participante elabora una pulsera o llavero con trenza de 15 pares.', 3.0, 65000.00, 10, 'Llevar hidratación y gorra.', 'ACTIVA', '2026-11-22 22:44:13'),
(21, 10, 5, 7, 'Mochilas y tejidos sabaneros', 'Taller de mochilas y tejidos sabaneros en Morroa con técnicas de crochet y telar vertical.', 3.0, 60000.00, 12, 'Llevar hidratación y gorra.', 'ACTIVA', '2026-11-22 22:44:13'),
(22, 4, 4, 4, 'Kayak en el Golfo de Morrosquillo', 'Recorrido en kayak por la costa del Golfo de Morrosquillo en Coveñas, con parada para nadar en aguas tranquilas.', 2.0, 75000.00, 12, 'Llegar 15 minutos antes.', 'ACTIVA', '2026-11-22 22:44:13'),
(23, 2, 4, 3, 'Paseo en lancha a Isla Múcura', 'Paseo en lancha desde Tolú hasta Isla Múcura en el archipiélago de San Bernardo, con tiempo de playa y almuerzo.', 8.0, 150000.00, 25, 'Llevar hidratación y gorra.', 'ACTIVA', '2026-11-22 22:44:13'),
(24, 11, 4, 9, 'Cabalgata por la sabana', 'Cabalgata por potreros y caminos reales de Los Palmitos, al ritmo de la vida ganadera de la sabana.', 3.0, 80000.00, 10, 'Llevar hidratación y gorra.', 'ACTIVA', '2026-11-22 22:44:13'),
(25, 4, 4, 4, 'Snorkel en Coveñas', 'Snorkel en los arrecifes cercanos a Coveñas para observar peces de colores y estrellas de mar (temporalmente inactiva).', 3.0, 120000.00, 10, 'Llevar hidratación y gorra.', 'INACTIVA', '2026-11-22 22:44:13'),
(26, 8, 1, 11, 'Festival gastronómico de Sincé', 'Festival gastronómico de Sincé con muestras de cocina sabanera, concurso de bollos y música en vivo (en preparación).', 5.0, 50000.00, 40, 'Menores de edad con acompañante.', 'BORRADOR', '2026-11-22 22:44:13'),
(33, 5, 2, 8, 'Ascenso al Cerro de Colosó', 'Experiencia registrada en Colosó.', 4.5, 85000.00, 12, NULL, 'BORRADOR', '2026-11-22 22:44:13');

